import { hash } from "./scoring.js";
import { finite } from "./stats.js";
import type { CombatEvent, DamageCategory, TrialResult } from "./types.js";

/** Observations transcribed from a controlled game recording, not generated by this engine. */
export interface CombatCapture {
  schemaVersion: 1;
  id: string;
  gameVersion: string;
  modelVersion: string;
  source: { url: string; sha256: string; fps: number };
  scenarioFingerprint: string;
  /** Damage-number precision of the capture; normally an integer display. */
  displayPrecision: number;
  /** Video time and the combat timer differ during pauses. */
  clock: "combat" | "animation";
  hits: {
    /** Use actor for one credited actor, or actors for a combined visible damage number. */
    actor?: string;
    actors?: string[];
    action: string;
    category: DamageCategory;
    atMs: number;
    amount: number;
    critical?: boolean;
  }[];
}
/** Passing is a numerical comparison, never automatic attestation that a recording is authentic. */
export function compareCombatCapture(
  trial: TrialResult,
  capture: CombatCapture,
  context: {
    gameVersion: string;
    modelVersion: string;
    scenarioFingerprint: string;
  },
) {
  if (
    capture.schemaVersion !== 1 ||
    !capture.id ||
    !capture.gameVersion ||
    capture.gameVersion !== context.gameVersion ||
    capture.modelVersion !== context.modelVersion ||
    capture.scenarioFingerprint !== context.scenarioFingerprint
  )
    throw new Error("Capture and simulation versions/configuration differ");
  if (
    !/^https:\/\//.test(capture.source.url) ||
    !/^[a-f0-9]{64}$/.test(capture.source.sha256)
  )
    throw new Error("Missing reproducible capture source");
  const timingToleranceMs =
    1000 / finite(capture.source.fps, "capture fps", 1, 240);
  const precision = finite(capture.displayPrecision, "display precision", 0, 1);
  if (!["combat", "animation"].includes(capture.clock))
    throw new Error("Capture must specify combat or animation clock");
  if (
    !Array.isArray(capture.hits) ||
    capture.hits.length < 1 ||
    capture.hits.length > 200_000
  )
    throw new Error("Missing capture damage events");
  const actorId = (value: unknown): value is string =>
    typeof value === "string" && /^[a-zA-Z0-9_-]{1,40}$/.test(value);
  const observed = capture.hits.map((hit) => {
    if ((hit.actor !== undefined) === (hit.actors !== undefined))
      throw new Error(
        "Capture must specify actor or composite actors exclusively",
      );
    const actors = hit.actors ?? [hit.actor!];
    if (
      !Array.isArray(actors) ||
      actors.length < 1 ||
      actors.length > 4 ||
      new Set(actors).size !== actors.length ||
      !actors.every(actorId) ||
      !hit.action ||
      !["direct", "anomaly", "disorder", "sheer", "special"].includes(
        hit.category,
      ) ||
      (hit.critical !== undefined && typeof hit.critical !== "boolean")
    )
      throw new Error("Invalid capture identity");
    return {
      ...hit,
      actors: [...actors].sort(),
      atMs: finite(hit.atMs, "hit time", 0, 3_600_000),
      amount: finite(hit.amount, "observed damage", 0, 1e15),
    };
  });
  const rows = trial.events.filter((event) => event.kind === "damage");
  const eventTime = (event: CombatEvent): number => {
    const value =
      capture.clock === "animation" ? event.animationAtMs : event.atMs;
    if (value === undefined || !Number.isFinite(value))
      throw new Error(`Missing ${capture.clock} timestamp in prediction`);
    return value;
  };
  interface VisibleDamage {
    actors: string[];
    action: string;
    category: DamageCategory;
    atMs: number;
    combatAtMs: number;
    animationAtMs?: number;
    triggerActor?: string;
    amount: number;
    critical?: boolean;
  }
  const events = new Map<string, VisibleDamage>();
  for (const [index, row] of rows.entries()) {
    const atMs = eventTime(row);
    if (
      !actorId(row.actor) ||
      !row.action ||
      !row.category ||
      typeof row.amount !== "number" ||
      !Number.isFinite(row.amount) ||
      row.amount < 0
    )
      throw new Error("Invalid predicted damage event");
    if (
      row.damageEventId !== undefined &&
      (typeof row.damageEventId !== "string" ||
        !/^[a-zA-Z0-9_-]{1,80}$/.test(row.damageEventId))
    )
      throw new Error("Invalid damage event identity");
    // Older traces have no event identity; never merge them just because timestamps coincide.
    const id =
      row.damageEventId === undefined
        ? `legacy:${index}`
        : `event:${row.damageEventId}`;
    const existing = events.get(id);
    if (existing) {
      if (
        existing.action !== row.action ||
        existing.category !== row.category ||
        existing.combatAtMs !== row.atMs ||
        existing.animationAtMs !== row.animationAtMs ||
        existing.triggerActor !== row.triggerActor
      )
        throw new Error(
          "Damage event group has inconsistent timing or identity",
        );
      existing.amount += row.amount;
      if (!existing.actors.includes(row.actor)) existing.actors.push(row.actor);
      if (existing.critical !== row.critical) existing.critical = undefined;
    } else
      events.set(id, {
        actors: [row.actor],
        action: row.action,
        category: row.category,
        atMs,
        combatAtMs: row.atMs,
        animationAtMs: row.animationAtMs,
        triggerActor: row.triggerActor,
        amount: row.amount,
        critical: row.critical,
      });
  }
  const predicted = [...events.values()].map((event) => ({
    ...event,
    actors: event.actors.sort(),
  }));
  const key = (hit: { actors: string[]; action: string; category: string }) =>
    `${hit.actors.join("+")}/${hit.action}/${hit.category}`;
  const groups = new Map<string, typeof observed>();
  for (const hit of observed) {
    const rows = groups.get(key(hit)) ?? [];
    rows.push(hit);
    groups.set(key(hit), rows);
  }
  const actualGroups = new Map<string, typeof predicted>();
  for (const hit of predicted) {
    const rows = actualGroups.get(key(hit)) ?? [];
    rows.push(hit);
    actualGroups.set(key(hit), rows);
  }
  const issues: {
    key: string;
    reason: string;
    index?: number;
    expected?: number;
    actual?: number;
  }[] = [];
  let checkedHits = 0;
  for (const id of new Set([...groups.keys(), ...actualGroups.keys()])) {
    const seen = (groups.get(id) ?? []).sort((a, b) => a.atMs - b.atMs),
      calculated = (actualGroups.get(id) ?? []).sort((a, b) => a.atMs - b.atMs);
    if (seen.length !== calculated.length)
      issues.push({
        key: id,
        reason: "Hit count mismatch",
        expected: seen.length,
        actual: calculated.length,
      });
    for (let i = 0; i < Math.min(seen.length, calculated.length); i++) {
      const observed = seen[i],
        computed = calculated[i];
      checkedHits++;
      if (
        observed.critical !== undefined &&
        observed.critical !== computed.critical
      )
        issues.push({
          key: id,
          index: i,
          reason: "Critical state differs; not a controlled comparison",
        });
      if (
        Math.abs(observed.amount - computed.amount!) >
        Math.max(precision, observed.amount * 0.01)
      )
        issues.push({
          key: id,
          index: i,
          reason: "Single-hit damage exceeds 1% tolerance",
          expected: observed.amount,
          actual: computed.amount,
        });
      if (Math.abs(observed.atMs - computed.atMs) > timingToleranceMs + 1e-7)
        issues.push({
          key: id,
          index: i,
          reason: "Hit timing exceeds one captured frame",
          expected: observed.atMs,
          actual: computed.atMs,
        });
    }
  }
  const totalObserved = observed.reduce((sum, hit) => sum + hit.amount, 0);
  const totalPredicted = finite(trial.total, "predicted total", 0);
  const totalError = Math.abs(totalPredicted - totalObserved);
  if (totalError > Math.max(precision * observed.length, totalObserved * 0.05))
    issues.push({
      key: "total",
      reason: "Rotation damage exceeds 5% tolerance",
      expected: totalObserved,
      actual: trial.total,
    });
  return {
    schemaVersion: 1 as const,
    captureId: capture.id,
    source: { ...capture.source },
    captureHash: hash(capture),
    ...context,
    clock: capture.clock,
    passed: issues.length === 0,
    requiresSourceReview: true as const,
    thresholds: {
      hitRelativeError: 0.01,
      totalRelativeError: 0.05,
      timingToleranceMs,
    },
    observedHits: observed.length,
    predictedHits: predicted.length,
    predictedAttributionRows: rows.length,
    checkedHits,
    totalObserved,
    totalPredicted: trial.total,
    totalRelativeError: totalObserved > 0 ? totalError / totalObserved : null,
    issues,
  };
}
